// Extract email data and build conversation payload
const emails = items[0].json;
const messageId = emails.id;
const threadId = emails.threadId;

// Parse headers to get sender, subject, date
const headers = emails.payload.headers || [];
const getHeader = (name) => headers.find(h => h.name.toLowerCase() === name.toLowerCase())?.value || '';

const fromEmail = getHeader('from');
const subject = getHeader('subject') || '(No Subject)';
const date = getHeader('date');

// Extract body (prefer text/plain, fallback to text/html)
let bodyText = '';
const parts = emails.payload.parts || [];

function extractBody(payload) {
  if (payload.mimeType === 'text/plain' && payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }
  if (payload.mimeType === 'text/html' && payload.body?.data && !bodyText) {
    // Simple HTML to text conversion
    const html = Buffer.from(payload.body.data, 'base64').toString('utf-8');
    return html.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
  }
  if (payload.parts) {
    for (const part of payload.parts) {
      const result = extractBody(part);
      if (result) return result;
    }
  }
  return '';
}

bodyText = extractBody(emails.payload);

// Build payload for POST /v1/conversations
const conversationPayload = {
  channel: 'email',
  subject: subject
};

// Return enriched data for downstream nodes
return [{
  json: {
    // Original email identifiers
    gmail_message_id: messageId,
    gmail_thread_id: threadId,
    // Sender info
    from_email: fromEmail,
    subject: subject,
    date: date,
    // Email body
    body: bodyText,
    // Payload for conversation creation
    conversation_payload: conversationPayload
  }
}];
